import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(true);
  
  const [printingId, setPrintingId] = useState(null);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [activeReviewTd, setActiveReviewTd] = useState(null);
  const [hoverRating, setHoverRating] = useState(null);
  
  // Состояния для универсального модального окна просмотра длинных комментариев/решений
  const [showViewModal, setShowViewModal] = useState(false);
  const [viewComment, setViewComment] = useState(null);
  
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  const [reviewForm, setReviewForm] = useState({
    test_drive_id: null,
    rating: 5,
    comment: ''
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      if (activeTab === 'purchases') {
        const res = await api.get('/purchases/my');
        setPurchases(res.data);
      } else if (activeTab === 'testDrives') {
        const res = await api.get('/test-drives/my');
        setTestDrives(res.data);
      } else if (activeTab === 'loans') {
        const res = await api.get('/loans/my');
        setLoans(res.data);
      } else if (activeTab === 'favorites') {
        const res = await api.get('/favorites/my');
        setFavorites(res.data);
      }
    } catch (err) {
      console.error('Ошибка при загрузке данных:', err);
    } finally {
      setLoading(false);
    }
  }, [activeTab]);

  useEffect(() => {
    if (activeTab !== 'profile') {
      fetchData();
    } else {
      setLoading(false);
    }
  }, [activeTab, fetchData]);

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/users/me', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: 'Ошибка при обновлении профиля' });
    }
  };

  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/reviews', {
        test_drive_id: activeReviewTd,
        rating: reviewForm.rating,
        comment: reviewForm.comment
      });
      setShowReviewModal(false);
      setActiveReviewTd(null);
      setReviewForm({ test_drive_id: null, rating: 5, comment: '' });
      fetchData();
    } catch (err) {
      console.error('Ошибка при отправке отзыва:', err);
    }
  };

  const handlePrintReceipt = (purchaseId) => {
    setPrintingId(purchaseId);
    setTimeout(() => {
      window.print();
      setPrintingId(null);
    }, 1000);
  };

  const openViewModal = (title, subtitle, comment) => {
    setViewComment({ title, subtitle, comment });
    setShowViewModal(true);
  };

  return (
    <motion.div 
      className={styles.container}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
    >
      <h1 className={styles.title}>Личный кабинет</h1>
      
      <div className={styles.tabs}>
        <button className={`${styles.tab} ${activeTab === 'profile' ? styles.active : ''}`} onClick={() => setActiveTab('profile')}>Профиль</button>
        <button className={`${styles.tab} ${activeTab === 'purchases' ? styles.active : ''}`} onClick={() => setActiveTab('purchases')}>Покупки</button>
        <button className={`${styles.tab} ${activeTab === 'testDrives' ? styles.active : ''}`} onClick={() => setActiveTab('testDrives')}>Тест-драйвы</button>
        <button className={`${styles.tab} ${activeTab === 'loans' ? styles.active : ''}`} onClick={() => setActiveTab('loans')}>Кредиты</button>
        <button className={`${styles.tab} ${activeTab === 'favorites' ? styles.active : ''}`} onClick={() => setActiveTab('favorites')}>Избранное</button>
      </div>

      {loading ? (
        <div className={styles.loading}>Загрузка данных...</div>
      ) : (
        <div className={styles.tabContent}>
          {activeTab === 'profile' && (
            <form onSubmit={handleProfileSubmit} className={styles.profileForm}>
              <div className={styles.field}>
                <label>ФИО</label>
                <input 
                  type="text" 
                  value={profileForm.full_name} 
                  onChange={(e) => setProfileForm({ ...profileForm, full_name: e.target.value })} 
                  required 
                />
              </div>
              <div className={styles.field}>
                <label>Телефон</label>
                <input 
                  type="text" 
                  value={profileForm.phone} 
                  onChange={(e) => setProfileForm({ ...profileForm, phone: e.target.value })} 
                  required 
                />
              </div>
              {updateStatus && (
                <p className={updateStatus.type === 'success' ? styles.successText : styles.errorText}>
                  {updateStatus.text}
                </p>
              )}
              <button type="submit" className={styles.submitBtn}>Сохранить изменения</button>
            </form>
          )}

          {activeTab === 'purchases' && (
            <div className={styles.cardsGrid}>
              {purchases.length === 0 ? <p>У вас пока нет зарегистрированных покупок.</p> : purchases.map(p => (
                <div key={p.id} className={`${styles.card} ${printingId === p.id ? styles.printReceipt : ''}`}>
                  <div className={styles.cardBody}>
                    <h4>{p.car?.brand} {p.car?.model}</h4>
                    <p>Стоимость: <strong>{p.price?.toLocaleString()} ₽</strong></p>
                    <p>Дата оформления: {new Date(p.created_at).toLocaleDateString()}</p>
                    <p>Статус: <span className={styles.statusSuccess}>Оплачено</span></p>
                    {p.comment && (
                      <p className={styles.clickableComment} onClick={() => openViewModal('Комментарий к покупке', `${p.car?.brand} ${p.car?.model}`, p.comment)}>
                        Посмотреть комментарий →
                      </p>
                    )}
                  </div>
                  <button className={styles.actionBtn} onClick={() => handlePrintReceipt(p.id)}>
                    {printingId === p.id ? 'Подготовка к печати...' : 'Печать чека'}
                  </button>
                </div>
              ))}
            </div>
          )}

          {activeTab === 'testDrives' && (
            <div className={styles.cardsGrid}>
              {testDrives.length === 0 ? <p>Вы пока не записывались на тест-драйвы.</p> : testDrives.map(td => (
                <div key={td.id} className={styles.card}>
                  <div className={styles.cardBody}>
                    <h4>{td.car?.brand} {td.car?.model}</h4>
                    <p>Дата: {new Date(td.date).toLocaleDateString()}</p>
                    <p>Время: {td.time}</p>
                    <p>Статус: <span className={styles[`status${td.status}`]}>{td.status === 'approved' ? 'Одобрен' : td.status === 'pending' ? 'В ожидании' : 'Отклонен'}</span></p>
                    {td.admin_comment && (
                      <p className={styles.clickableComment} onClick={() => openViewModal('Решение менеджера', `Тест-драйв: ${td.car?.brand} ${td.car?.model}`, td.admin_comment)}>
                        Посмотреть ответ →
                      </p>
                    )}
                  </div>
                  {td.status === 'approved' && !td.has_review && (
                    <button className={styles.actionBtn} onClick={() => { setActiveReviewTd(td.id); setShowReviewModal(true); }}>
                      Оставить отзыв
                    </button>
                  )}
                </div>
              ))}
            </div>
          )}

          {activeTab === 'loans' && (
            <div className={styles.cardsGrid}>
              {loans.length === 0 ? <p>У вас нет активных кредитных заявок.</p> : loans.map(l => (
                <div key={l.id} className={styles.card}>
                  <div className={styles.cardBody}>
                    <h4>{l.car?.brand} {l.car?.model}</h4>
                    <p>Сумма кредита: {l.amount?.toLocaleString()} ₽</p>
                    <p>Срок: {l.term_months} мес.</p>
                    <p>Ставка: {l.interest_rate}%</p>
                    <p>Ежемесячный платёж: <strong>{l.monthly_payment?.toLocaleString()} ₽/мес.</strong></p>
                    <p>Статус: <span className={styles[`status${l.status}`]}>{l.status === 'approved' ? 'Одобрен' : l.status === 'pending' ? 'На рассмотрении' : 'Отклонен'}</span></p>
                    {l.comment && (
                      <p className={styles.clickableComment} onClick={() => openViewModal('Комментарий по кредиту', `Кредит на ${l.car?.brand} ${l.car?.model}`, l.comment)}>
                        Посмотреть решение →
                      </p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {activeTab === 'favorites' && (
            <div className={styles.cardsGrid}>
              {favorites.length === 0 ? <p>Список избранного пуст.</p> : favorites.map(f => (
                <div key={f.id} className={styles.card}>
                  <div className={styles.cardBody}>
                    <h4>{f.brand} {f.model}</h4>
                    <p>Цена: <strong>{f.price?.toLocaleString()} ₽</strong></p>
                  </div>
                  <Link to={`/cars/${f.id}`} className={styles.actionBtnLink}>Перейти к автомобилю</Link>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* УНИВЕРСАЛЬНОЕ МОДАЛЬНОЕ ОКНО ДЛЯ ПРОСМОТРА ДЛИННЫХ КОММЕНТАРИЕВ И РЕШЕНИЙ */}
      <AnimatePresence>
        {showViewModal && viewComment && (
          <motion.div 
            className={styles.modalOverlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => { setShowViewModal(false); setViewComment(null); }}
          >
            <motion.div 
              className={styles.modalContent}
              initial={{ scale: 0.95, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 20 }}
              transition={{ duration: 0.2 }}
              onClick={(e) => e.stopPropagation()}
            >
              <button className={styles.modalClose} onClick={() => { setShowViewModal(false); setViewComment(null); }}>✕</button>
              <h3 className={styles.modalTitle}>{viewComment.title}</h3>
              <p className={styles.modalSubtitle}>{viewComment.subtitle}</p>
              
              <div className={styles.modalField}>
                <div style={{ 
                  background: 'rgba(128, 128, 128, 0.08)', 
                  padding: '1.2rem', 
                  borderRadius: '14px', 
                  fontStyle: 'italic', 
                  lineHeight: '1.6', 
                  borderLeft: '4px solid var(--primary)', 
                  color: 'var(--text)',
                  wordBreak: 'break-word',
                  overflowWrap: 'break-word',
                  whiteSpace: 'pre-wrap'
                }}>
                  {viewComment.comment}
                </div>
              </div>
              
              <div className={styles.modalActions}>
                <button 
                  type="button" 
                  className={styles.submitBtn} 
                  onClick={() => { setShowViewModal(false); setViewComment(null); }}
                >
                  Закрыть
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* МОДАЛЬНОЕ ОКНО ДЛЯ ОТПРАВКИ ОТЗЫВА */}
      <AnimatePresence>
        {showReviewModal && (
          <motion.div 
            className={styles.modalOverlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => { setShowReviewModal(false); setActiveReviewTd(null); }}
          >
            <motion.div 
              className={styles.modalContent}
              initial={{ scale: 0.95, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 20 }}
              transition={{ duration: 0.2 }}
              onClick={(e) => e.stopPropagation()}
            >
              <button className={styles.modalClose} onClick={() => { setShowReviewModal(false); setActiveReviewTd(null); }}>✕</button>
              <h3 className={styles.modalTitle}>Оставить отзыв о тест-драйве</h3>
              
              <form onSubmit={handleReviewSubmit}>
                <div className={styles.modalField}>
                  <label>Оценка автомобиля</label>
                  <div className={styles.ratingStars}>
                    {[1, 2, 3, 4, 5].map((star) => {
                      return (
                        <span 
                          key={star}
                          className={`${styles.star} ${star <= (hoverRating || reviewForm.rating) ? styles.starActive : ''}`}
                          onClick={() => setReviewForm({ ...reviewForm, rating: star })}
                          onMouseEnter={() => setHoverRating(star)}
                          onMouseLeave={() => setHoverRating(null)}
                        >
                          ★
                        </span>
                      );
                    })}
                  </div>
                </div>
                
                <div className={styles.modalField}>
                  <label>Ваш отзыв</label>
                  <textarea 
                    placeholder="Расскажите, как прошёл тест-драйв, понравилась ли управляемость и динамика автомобиля..." 
                    value={reviewForm.comment}
                    onChange={(e) => setReviewForm({ ...reviewForm, comment: e.target.value })}
                    className={styles.modalTextarea}
                    rows="4"
                    required
                  />
                </div>
                
                <div className={styles.modalActions}>
                  <button 
                    type="button" 
                    className={styles.cancelBtn} 
                    onClick={() => { setShowReviewModal(false); setActiveReviewTd(null); }}
                  >
                    Отмена
                  </button>
                  <button type="submit" className={styles.submitBtn}>
                    Отправить отзыв
                  </button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default UserDashboard;
